import html
from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory product catalog (replace with DB in production)
products = {
    1: {
        "id": 1,
        "name": "Example Product",
        "description": "A sample product description."
    }
}


def render_product_html(product):
    """
    Render a product as an HTML snippet.
    All user-supplied fields are HTML-escaped before embedding to prevent XSS.
    """
    safe_name = html.escape(product["name"])
    safe_description = html.escape(product["description"])
    return (
        f"<div class='product'>"
        f"<h2>{safe_name}</h2>"
        f"<p>{safe_description}</p>"
        f"</div>"
    )


@app.route("/api/catalog", methods=["GET"])
def list_products():
    """Return all products as JSON."""
    return jsonify(list(products.values()))


@app.route("/api/catalog/<int:product_id>", methods=["GET"])
def get_product(product_id):
    """Return a single product as JSON."""
    product = products.get(product_id)
    if not product:
        return jsonify({"error": "Product not found"}), 404
    return jsonify(product)


@app.route("/api/catalog/<int:product_id>/html", methods=["GET"])
def get_product_html(product_id):
    """
    Return a single product rendered as HTML.
    Uses html.escape() on all user-supplied fields to prevent stored XSS.
    """
    product = products.get(product_id)
    if not product:
        return "<p>Product not found</p>", 404
    return render_product_html(product), 200, {"Content-Type": "text/html"}


@app.route("/api/catalog", methods=["POST"])
def create_product():
    """Create a new product. Description is stored as-is (escaped on output)."""
    data = request.get_json()
    if not data or "name" not in data or "description" not in data:
        return jsonify({"error": "name and description are required"}), 400
    new_id = max(products.keys(), default=0) + 1
    products[new_id] = {
        "id": new_id,
        "name": data["name"],
        "description": data["description"],
    }
    return jsonify(products[new_id]), 201


if __name__ == "__main__":
    app.run(debug=False)

import html
from flask import Flask, request, jsonify

app = Flask(__name__)

# Simulated product database
products = {
    "1": {"id": "1", "name": "Widget A", "description": "A great widget"},
    "2": {"id": "2", "name": "Widget B", "description": "An even better widget"},
}


def render_product_html(product_name, product_description):
    """Render a product as an HTML snippet."""
    # Escape user-supplied fields before embedding in HTML (CWE-79 fix)
    safe_name = html.escape(product_name)
    safe_description = html.escape(product_description)
    return f"<div><h2>{safe_name}</h2><p>{safe_description}</p></div>"


@app.route("/api/products", methods=["GET"])
def list_products():
    return jsonify(list(products.values()))


@app.route("/api/products/<product_id>", methods=["GET"])
def get_product(product_id):
    product = products.get(product_id)
    if not product:
        return jsonify({"error": "Product not found"}), 404
    return jsonify(product)


@app.route("/api/products/search", methods=["GET"])
def search_products():
    query = request.args.get("q", "")
    results = [
        p for p in products.values()
        if query.lower() in p["name"].lower() or query.lower() in p["description"].lower()
    ]
    return jsonify(results)


@app.route("/api/products/preview", methods=["GET"])
def preview_product():
    # LINE 42 FIX: user-supplied name/description are now escaped before HTML rendering
    name = request.args.get("name", "")
    description = request.args.get("description", "")
    # BEFORE (vulnerable): html_output = f"<div><h2>{name}</h2><p>{description}</p></div>"
    # AFTER  (safe):       html.escape() applied to each user-supplied field
    html_output = render_product_html(name, description)
    return html_output, 200, {"Content-Type": "text/html"}


@app.route("/api/products", methods=["POST"])
def create_product():
    data = request.get_json()
    if not data or "name" not in data:
        return jsonify({"error": "Missing product name"}), 400
    product_id = str(len(products) + 1)
    products[product_id] = {
        "id": product_id,
        "name": data["name"],
        "description": data.get("description", ""),
    }
    return jsonify(products[product_id]), 201


if __name__ == "__main__":
    app.run(debug=False)

from flask import Blueprint, jsonify, request
from markupsafe import escape
from models import Product, db

products_bp = Blueprint('products', __name__)


@products_bp.route('/api/products', methods=['GET'])
def list_products():
    products = Product.query.all()
    return jsonify([
        {
            'id': p.id,
            'name': p.name,
            'price': p.price,
        }
        for p in products
    ])


@products_bp.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    product = Product.query.get(product_id)
    if not product:
        return jsonify({'error': 'Product not found'}), 404

    # FIX (CWE-79): Escape user-supplied description before embedding in HTML
    # Previously: f"<div class='product-description'>{product.description}</div>"
    # This allowed stored XSS if a malicious description was saved to the DB.
    html_description = f"<div class='product-description'>{escape(product.description)}</div>"

    return jsonify({
        'id': product.id,
        'name': product.name,
        'description': html_description,
        'price': product.price,
        'category': product.category,
    })


@products_bp.route('/api/products', methods=['POST'])
def create_product():
    data = request.get_json()
    product = Product(
        name=data['name'],
        description=data['description'],
        price=data['price'],
        category=data.get('category', ''),
    )
    db.session.add(product)
    db.session.commit()
    return jsonify({'id': product.id}), 201


@products_bp.route('/api/products/<int:product_id>', methods=['PUT'])
def update_product(product_id):
    product = Product.query.get(product_id)
    if not product:
        return jsonify({'error': 'Product not found'}), 404
    data = request.get_json()
    if 'name' in data:
        product.name = data['name']
    if 'description' in data:
        product.description = data['description']
    if 'price' in data:
        product.price = data['price']
    if 'category' in data:
        product.category = data['category']
    db.session.commit()
    return jsonify({'status': 'updated'})
